                        INSERT INTO command_log
                            (command_key, actor_id, operation, request_hash, response_status, response_body, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                        """,
                commandKey, actorId, operation, requestHash, responseStatus, responseBody, now);
