     * @param responseBody   首次执行的响应体 JSON
     * @param createdAt      首次执行时间（Asia/Shanghai）
     */
    public record CommandLog(
            String commandKey,
            String actorId,
            String operation,
            String requestHash,
            int responseStatus,
            String responseBody,
            LocalDateTime createdAt) {
    }

