75	                        .header(ACTOR_HEADER, actor)
76	                        .contentType(MediaType.APPLICATION_JSON)
77	                        .content(objectMapper.writeValueAsString(body)))
78	                .andReturn();
79	    }
80	
81	    private MvcResult inspect(String actor, String evidenceKey, String commandKey,
82	                              boolean passed) throws Exception {
83	        Map<String, Object> body = new LinkedHashMap<>();
84	        body.put("commandKey", commandKey);
85	        body.put("passed", passed);
86	        body.put("note", "routine");
87	        return mockMvc.perform(post("/api/evidence/{key}/seal-inspections", evidenceKey)
88	                        .header(ACTOR_HEADER, actor)
89	                        .contentType(MediaType.APPLICATION_JSON)
90	                        .content(objectMapper.writeValueAsString(body)))
91	                .andReturn();
92	    }
93	
94	    private JsonNode chain(String evidenceKey) throws Exception {
95	        MvcResult result = mockMvc.perform(get("/api/evidence/{key}/custody-chain", evidenceKey))
96	                .andReturn();
97	        assertThat(result.getResponse().getStatus()).isEqualTo(200);
98	        return objectMapper.readTree(result.getResponse().getContentAsString());
99	    }
100	
101	    @Test
102	    void intakeCreatesSealedEvidenceWithActorAsCustodian() throws Exception {
103	        String evidenceKey = uniqueKey("EV");
104	        MvcResult result = intake("alice", uniqueKey("CMD"), evidenceKey);
105	
106	        assertThat(result.getResponse().getStatus()).isEqualTo(201);
107	        JsonNode body = objectMapper.readTree(result.getResponse().getContentAsString());
108	        assertThat(body.get("evidenceKey").asText()).isEqualTo(evidenceKey);
109	        assertThat(body.get("custodianId").asText()).isEqualTo("alice");
110	        assertThat(body.get("status").asText()).isEqualTo("SEALED");
111	        assertThat(body.get("caseKey").asText()).isEqualTo("CASE-1");
112	    }
113	
114	    @Test
115	    void intakeDuplicateEvidenceKeyReturns409() throws Exception {
116	        String evidenceKey = uniqueKey("EV");
117	        assertThat(intake("alice", uniqueKey("CMD"), evidenceKey).getResponse().getStatus())
118	                .isEqualTo(201);
119	        assertThat(intake("alice", uniqueKey("CMD"), evidenceKey).getResponse().getStatus())
120	                .isEqualTo(409);
121	    }
122	
123	    @Test
124	    void intakeIdempotentReplayReturnsFirstResult() throws Exception {
125	        String evidenceKey = uniqueKey("EV");
126	        String commandKey = uniqueKey("CMD");
127	        MvcResult first = intake("alice", commandKey, evidenceKey);
128	        MvcResult replay = intake("alice", commandKey, evidenceKey);
